Validation failed for tool "propose_state_delta":
  - promises.0.promise: must have required properties promise

Received arguments:
{
  "claims": [
    {
      "entity": "loc-communal-kitchen",
      "attribute": "sensory_description",
      "quote": "The kitchen hit her with a wash of frying oil and steam, the smell so sharp it made her sinuses ache; kerosene stoves blackened at their rims, benches scarred by bowls, and an open hatch—if it could be called that—looked toward the alley.",
      "value": "frying oil and steam; kerosene stoves; scarred benches; an opening toward Alley 13"
    },
    {
      "entity": "loc-communal-kitchen",
      "attribute": "poltergeist_activity",
      "quote": "A pot clattered from an empty stall and everyone jerked as if struck. ... A pot clattered again; this time two plates on a shelf rattled as if someone had run a hand along their edge.",
      "value": "pots clatter from empty stalls; plates rattle on shelves"
    },
    {
      "entity": "loc-alley-13",
      "attribute": "connection_to_communal_kitchen",
      "quote": "the communal kitchen opened like a throat. ... an open hatch—if it could be called that—looked toward the alley.",
      "value": "communal kitchen opens toward Alley 13 (functional connection noted in scene)"
    },
    {
      "entity": "char-elder-storyteller",
      "attribute": "appearance_and_demeanor",
      "quote": "He was small-boned and folded like old paper; he eased a folded packet from his sleeve and leafed an edge open, letting the smell of brittle, incense-scented notes meet the kitchen smoke. He spoke with the sort of voice that had the whole room learn to listen: slow, economical, the vowels rounded like coins.",
      "value": "small-boned, carries a folded packet of notes, speaks slowly and economically"
    },
    {
      "entity": "char-elder-storyteller",
      "attribute": "role_in_scene",
      "quote": "\"This is an old hurt,\" he said, not to Mercy alone but to the room. \"Not the sort you cover with red paper and call it whole. It answers—\" he hesitated, choosing, \"—to names. To stories people tuck under their mats.\"",
      "value": "hints that the haunting answers to names and buried stories; positions himself as keeper of oral knowledge"
    },
    {
      "entity": "char-mercy-chan",
      "attribute": "tactical_response",
      "quote": "She lit a thin stick of incense and let it burn down until the smoke thickened into a pale column. Then she did what she always did: a low, patient naming, a small phrase to prod what hid in closed places.",
      "value": "performs low naming with incense to prod spirit activity"
    },
    {
      "entity": "char-mercy-chan",
      "attribute": "ritual_cost_occurence",
      "quote": "Mercy felt her sight narrow for a second, as if a curtain had been drawn across the edges of what she could see; tears prickled though she did not want them.",
      "value": "diagnostic ritual causes temporary narrowing of sight and emotional bleed (tears)"
    },
    {
      "entity": "faction-residents-commune",
      "attribute": "reaction_in_kitchen",
      "quote": "People crowded the benches, leaning in as if conversation itself might keep the noise at bay. ... The commune smelled of laundry, of woodsmoke, and the metallic tang of ration tins left half-open on the table.",
      "value": "residents gather in kitchen, anxious; use communal space to share information and comfort"
    },
    {
      "entity": "char-elder-storyteller",
      "attribute": "relationship_with_mercy",
      "quote": "\"You cannot fix this alone, child. The City remembers more than you can ask it to carry.\"",
      "value": "addresses Mercy as 'child' and implies expectation that Mercy will need community support (tenor: admonitory but not hostile)"
    }
  ],
  "present_entities": [
    "char-mercy-chan",
    "char-neighbor-lei",
    "char-elder-storyteller",
    "faction-residents-commune",
    "loc-alley-13",
    "loc-communal-kitchen",
    "obj-incense-burner"
  ],
  "pays_off": [],
  "promises": [
    {
      "id": "promise-s-001-01",
      "contract_id": "promise-s-001-01",
      "quote": "She said to the room, quiet and clear, \"I will go look at the yard.\""
    }
  ]
}
